// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner, address caller, address finalOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(caller != newOwner);

        // current owner is address(0); it legitimately transfers ownership to newOwner
        vm.prank(address(0));
        c.transferOwnership(newOwner);

        // a caller that is NOT the owner attempts another transfer
        vm.prank(caller);
        try c.transferOwnership(finalOwner) {
            // non-owner cannot change ownership
            assertTrue(c.owner() == newOwner);
        } catch {
            // reference reverts for non-owner callers: ownership untouched
            assertTrue(c.owner() == newOwner);
        }
    }
}
